import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';
import { TIER_DISCOUNTS } from '../src/customers.js';

test('createInvoice creates a draft invoice with enriched lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });

  assert.equal(r.ok, true);
  const invoice = r.value;
  assert.equal(invoice.customerId, 'C-001');
  assert.equal(invoice.issueDate, '2024-01-15');
  assert.equal(invoice.status, 'draft');
  assert.equal(invoice.lines.length, 2);

  assert.equal(invoice.lines[0].sku, 'DES-HOUR');
  assert.equal(invoice.lines[0].name, 'Design work (hour)');
  assert.equal(invoice.lines[0].qty, 10);
  assert.equal(invoice.lines[0].unitPrice, 8500);
  assert.equal(invoice.lines[0].vatRate, 21);

  assert.equal(invoice.lines[1].sku, 'DEV-HOUR');
  assert.equal(invoice.lines[1].name, 'Development (hour)');
  assert.equal(invoice.lines[1].qty, 5);
  assert.equal(invoice.lines[1].unitPrice, 9500);
  assert.equal(invoice.lines[1].vatRate, 21);
});

test('createInvoice rejects unknown customer', () => {
  const r = createInvoice({
    customerId: 'C-999',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice rejects invalid date format', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '15/01/2024',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice rejects non-existent date', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-30',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice rejects empty lines array', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [],
  });

  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice rejects non-integer quantity', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1.5 }],
  });

  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice rejects zero quantity', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 0 }],
  });

  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice rejects negative quantity', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: -5 }],
  });

  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice rejects unknown SKU', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'UNKNOWN-SKU', qty: 1 }],
  });

  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice handles VAT-exempt products', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-06-01',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 2 }],
  });

  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].vatRate, 0);
  assert.equal(r.value.lines[0].unitPrice, 60000);
});

test('createInvoice does not mutate input', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 1 }];
  const linesBefore = JSON.stringify(lines);

  createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines,
  });

  assert.equal(JSON.stringify(lines), linesBefore);
});

test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 10, unitPrice: 8500 }), 85000);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 5, unitPrice: 9500 }), 47500);
});

test('lineTotal handles zero quantity', () => {
  assert.equal(lineTotal({ qty: 0, unitPrice: 8500 }), 0);
});

test('invoiceTotals sums line totals', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });

  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);
  const expected = 10 * 8500 + 5 * 9500;
  assert.equal(totals.subtotal, expected);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, expected);
});

test('invoiceTotals returns zero for empty invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals with single line', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-06-01',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);
  assert.equal(totals.subtotal, 120000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 120000);
});

test('addLine adds a new line to an invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });

  assert.equal(r.ok, true);
  const invoice = r.value;

  const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 5 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(result.value.lines[1].qty, 5);
});

test('addLine increases qty if SKU already exists', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });

  assert.equal(r.ok, true);
  const invoice = r.value;

  const result = addLine(invoice, { sku: 'DES-HOUR', qty: 5 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].qty, 15);
});

test('addLine rejects invalid qty', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });

  assert.equal(r.ok, true);
  const invoice = r.value;

  const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 1.5 });
  assert.deepEqual(result, { ok: false, error: 'QTY_INVALID' });
});

test('addLine rejects unknown SKU', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });

  assert.equal(r.ok, true);
  const invoice = r.value;

  const result = addLine(invoice, { sku: 'UNKNOWN-SKU', qty: 1 });
  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine refuses to modify non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'issued',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 8500, vatRate: 21 }],
  };

  const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 5 });
  assert.deepEqual(result, { ok: false, error: 'NOT_DRAFT' });
});

test('addLine does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });

  assert.equal(r.ok, true);
  const invoice = r.value;
  const before = JSON.stringify(invoice);

  addLine(invoice, { sku: 'DEV-HOUR', qty: 5 });

  assert.equal(JSON.stringify(invoice), before);
});

test('removeLine removes a line from an invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });

  assert.equal(r.ok, true);
  const invoice = r.value;

  const result = removeLine(invoice, 'DES-HOUR');
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].sku, 'DEV-HOUR');
});

test('removeLine rejects if SKU not found', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });

  assert.equal(r.ok, true);
  const invoice = r.value;

  const result = removeLine(invoice, 'UNKNOWN-SKU');
  assert.deepEqual(result, { ok: false, error: 'LINE_NOT_FOUND' });
});

test('removeLine rejects if it would remove the last line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });

  assert.equal(r.ok, true);
  const invoice = r.value;

  const result = removeLine(invoice, 'DES-HOUR');
  assert.deepEqual(result, { ok: false, error: 'NO_LINES' });
});

test('removeLine refuses to modify non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'issued',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 8500, vatRate: 21 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 5, unitPrice: 9500, vatRate: 21 },
    ],
  };

  const result = removeLine(invoice, 'DES-HOUR');
  assert.deepEqual(result, { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });

  assert.equal(r.ok, true);
  const invoice = r.value;
  const before = JSON.stringify(invoice);

  removeLine(invoice, 'DEV-HOUR');

  assert.equal(JSON.stringify(invoice), before);
});

test('issueInvoice assigns number and changes status to issued', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });

  assert.equal(r.ok, true);
  const invoice = r.value;

  const result = issueInvoice(invoice, []);
  assert.equal(result.ok, true);
  assert.equal(result.value.status, 'issued');
  assert.equal(result.value.number, 'INV-2024-0001');
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2024-01-15');
  assert.equal(result.value.lines.length, 1);
});

test('issueInvoice uses existing numbers to find next number', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });

  assert.equal(r.ok, true);
  const invoice = r.value;

  const result = issueInvoice(invoice, ['INV-2024-0001', 'INV-2024-0002']);
  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2024-0003');
});

test('issueInvoice rejects non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'issued',
    number: 'INV-2024-0001',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 8500, vatRate: 21 }],
  };

  const result = issueInvoice(invoice, []);
  assert.deepEqual(result, { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });

  assert.equal(r.ok, true);
  const invoice = r.value;
  const before = JSON.stringify(invoice);

  issueInvoice(invoice, ['INV-2024-0001']);

  assert.equal(JSON.stringify(invoice), before);
});

test('lineDiscount calculates discount from lineTotal', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 8500, discountPercent: 10 }), 8500);
  assert.equal(lineDiscount({ qty: 10, unitPrice: 8500, discountPercent: 0 }), 0);
  assert.equal(lineDiscount({ qty: 100, unitPrice: 100, discountPercent: 25 }), 2500);
});

test('lineDiscount handles decimal discount percent', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 8500, discountPercent: 12.5 }), 10625);
  assert.equal(lineDiscount({ qty: 8, unitPrice: 10000, discountPercent: 33.33 }), 26664);
});

test('lineDiscount defaults to 0 when discountPercent omitted', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 8500 }), 0);
});

test('createInvoice accepts discountPercent on lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 10 }],
  });

  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 10);
});

test('createInvoice rejects invalid discount percent', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 150 }],
  });

  assert.deepEqual(r, { ok: false, error: 'DISCOUNT_INVALID' });
});

test('createInvoice rejects negative discount percent', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: -10 }],
  });

  assert.deepEqual(r, { ok: false, error: 'DISCOUNT_INVALID' });
});

test('createInvoice rejects non-numeric discount percent', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 'not a number' }],
  });

  assert.deepEqual(r, { ok: false, error: 'DISCOUNT_INVALID' });
});

test('invoiceTotals calculates discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 0 },
    ],
  });

  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);
  const subtotal = 10 * 8500 + 5 * 9500;
  const discount = 10 * 8500 * 0.1;
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, discount);
  assert.equal(totals.total, subtotal - discount);
});

test('invoiceTotals with multiple discounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
