test('addLine refuses to modify non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'issued',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 8500, vatRate: 21 }],
  };

  const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 5 });
