test('renderInvoiceText shows VAT line', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });

  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');

  const vatLineIndex = lines.findIndex((line) => line.startsWith('VAT:'));
  assert.ok(vatLineIndex > 0, 'VAT line should exist');
  assert.match(lines[vatLineIndex], /^VAT: €/);
  assert.equal(lines[vatLineIndex + 1], 'Total: €1,028.50');
});

test('renderInvoiceText hides VAT line when zero', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  });

  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);

