});

test('renderInvoiceText shows discount and VAT lines', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 10 }],
  });

  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');

  const discountLineIndex = lines.findIndex((line) => line.startsWith('Discount:'));
  const vatLineIndex = lines.findIndex((line) => line.startsWith('VAT:'));
  assert.ok(discountLineIndex > 0, 'Discount line should exist');
  assert.ok(vatLineIndex > discountLineIndex, 'VAT line should come after discount');
  assert.equal(lines[vatLineIndex + 1], 'Total: €7,256.50');
});
